describe('Background Sync Notification', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's base URL
    });

    it('should display a toast notification when background sync completes', () => {
        // Simulate background sync completion
        cy.intercept('POST', '/api/sync', {
            statusCode: 200,
            body: { message: 'Sync completed successfully' },
        }).as('syncRequest');

        // Trigger the background sync
        cy.get('button#start-sync').click(); // Adjust selector to your application's button

        // Wait for the sync request to complete
        cy.wait('@syncRequest');

        // Assert that the toast notification is displayed
        cy.get('.toast-notification') // Adjust selector to your application's toast notification
            .should('be.visible')
            .and('contain', 'Sync completed successfully');
    });

    it('should not display a toast notification if background sync fails', () => {
        // Simulate background sync failure
        cy.intercept('POST', '/api/sync', {
            statusCode: 500,
            body: { message: 'Sync failed' },
        }).as('syncRequest');

        // Trigger the background sync
        cy.get('button#start-sync').click(); // Adjust selector to your application's button

        // Wait for the sync request to complete
        cy.wait('@syncRequest');

        // Assert that the toast notification is not displayed
        cy.get('.toast-notification') // Adjust selector to your application's toast notification
            .should('not.exist');
    });
});
